import {PNG} from 'pngjs';
import {gzipSync} from 'node:zlib';
const catalog=structuredClone(atlasCatalog),source={title:'Synthetic survey',datum:'AHD',survey_date:'2020',quality:'measured',resolution_m:1000,source_url:'https://example.invalid/survey',grid:{projection:'EPSG:4326',width:16,height:16,chunk_size:16,transform:[.0125,0,144.9,0,-.0125,-37.9],chunks:{'0/0':'data/test-cells.gz'}}};catalog.regions[0].rasters=[source];catalog.regions[0].status='raster';const bytes=Buffer.alloc(16*16*4);for(let i=0;i<256;i++)bytes.writeFloatLE(i%16<7?8:20,i*4);const compressed=gzipSync(bytes),values={'beaches.json':Buffer.from(JSON.stringify(atlasBeaches)),'data/catalog.json':Buffer.from(JSON.stringify(catalog)),'data/example-bay-contours.json':Buffer.from(JSON.stringify(atlasContours)),'data/second-bay-contours.json':Buffer.from(JSON.stringify(atlasContours)),'data/test-cells.gz':compressed},files=Object.fromEntries(Object.entries(values).map(([path,body])=>[path,{hash:createHash('sha256').update(body).digest('hex'),bytes:body.length,label:path}]));
